from collections import defaultdict

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = defaultdict(int)
    for row in grid:
        for v in row:
            counts[v] += 1
    bg = max(counts, key=counts.get)
    seen, objs = set(), []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]; seen.add((r, c)); pts = []
            while stack:
                y, x = stack.pop(); pts.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == color and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            r0, r1 = min(y for y,x in pts), max(y for y,x in pts)
            c0, c1 = min(x for y,x in pts), max(x for y,x in pts)
            shape = tuple(sorted((y-r0,x-c0) for y,x in pts))
            objs.append({'color':color, 'pts':pts, 'shape':shape,
                         'r0':r0, 'r1':r1, 'c0':c0, 'c1':c1,
                         'center':(sum(y for y,x in pts)/len(pts),sum(x for y,x in pts)/len(pts))})
    guides = []
    for o in objs:
        r0,r1,c0,c1=o['r0'],o['r1'],o['c0'],o['c1']; pts=set(o['pts'])
        for cr in (r0,r1):
            for cc in (c0,c1):
                if pts == ({(y,cc) for y in range(r0,r1+1)} | {(cr,x) for x in range(c0,c1+1)}):
                    guides.append((len(pts),o,cr,cc))
    if not guides:
        return [row[:] for row in grid]
    _,guide,cr,cc=max(guides,key=lambda t:t[0])
    dr=-1 if cr==guide['r1'] else 1
    dc=-1 if cc==guide['c1'] else 1
    inside=[]; outside=[]
    for o in objs:
        if o is guide: continue
        y,x=o['center']
        (inside if (y-cr)*dr>0 and (x-cc)*dc>0 else outside).append(o)
    matches=[]
    for a in inside:
        for b in outside:
            if a['shape']==b['shape']:
                # prefer the closest matching outer copy to the guide
                y,x=b['center']; matches.append(((y-cr)**2+(x-cc)**2,b))
    out=[row[:] for row in grid]
    if matches:
        target=min(matches,key=lambda t:t[0])[1]
        for y,x in target['pts']: out[y][x]=guide['color']
    return out
